insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('kashgar-g1', 'kashgar', 5, 'Мой и твой', '{}'::int[], 'phrases', '{"text": "«Мой» по-уйгурски — это окончание: после гласной -м, после согласной -им. «Твой» — -ң или -иң.", "examples": [{"ug": "ата → атам", "ru": "мой отец"}, {"ug": "ата → атаң", "ru": "твой отец"}, {"ug": "қиз → қизим", "ru": "моя дочь"}, {"ug": "қиз → қизиң", "ru": "твоя дочь"}]}'::jsonb, '[{"ug": "атам", "ru": "мой отец", "group": "ата"}, {"ug": "атаң", "ru": "твой отец", "group": "ата"}, {"ug": "анам", "ru": "моя мать", "group": "ана"}, {"ug": "анаң", "ru": "твоя мать", "group": "ана"}, {"ug": "апам", "ru": "моя мама", "group": "апа"}, {"ug": "апаң", "ru": "твоя мама", "group": "апа"}, {"ug": "момам", "ru": "моя бабушка", "group": "мома"}, {"ug": "момаң", "ru": "твоя бабушка", "group": "мома"}, {"ug": "қизим", "ru": "моя дочь", "group": "қиз"}, {"ug": "қизиң", "ru": "твоя дочь", "group": "қиз"}]'::jsonb);
