insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('turpan-g1', 'turpan', 3, 'Его и её', '{}'::int[], 'phrases', '{"text": "«Его» и «её» звучат одинаково: после гласной -си, после согласной -и. Конечная а перед -си становится и: ата → атиси.", "examples": [{"ug": "ата → атиси", "ru": "его (её) отец"}, {"ug": "ака → акиси", "ru": "его старший брат"}, {"ug": "қиз → қизи", "ru": "его дочь"}, {"ug": "ит → ити", "ru": "его собака"}]}'::jsonb, '[{"ug": "атиси", "ru": "его отец", "group": "ата"}, {"ug": "атам", "ru": "мой отец", "group": "ата"}, {"ug": "аниси", "ru": "его мать", "group": "ана"}, {"ug": "анаң", "ru": "твоя мать", "group": "ана"}, {"ug": "акиси", "ru": "его старший брат", "group": "ака"}, {"ug": "акам", "ru": "мой старший брат", "group": "ака"}, {"ug": "момиси", "ru": "его бабушка", "group": "мома"}, {"ug": "қизи", "ru": "его дочь", "group": "қиз"}, {"ug": "ити", "ru": "его собака", "group": "ит"}, {"ug": "итим", "ru": "моя собака", "group": "ит"}]'::jsonb);
