insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('turpan-g2', 'turpan', 7, 'Наш и ваш', '{}'::int[], 'phrases', '{"text": "«Наш» — -миз после гласной, -имиз после согласной. Вежливое «ваш» — -ңиз или -иңиз. Конечная а здесь тоже становится и.", "examples": [{"ug": "ата → атимиз", "ru": "наш отец"}, {"ug": "ата → атиңиз", "ru": "ваш отец"}, {"ug": "қиз → қизимиз", "ru": "наша дочь"}, {"ug": "қиз → қизиңиз", "ru": "ваша дочь"}]}'::jsonb, '[{"ug": "атимиз", "ru": "наш отец", "group": "ата"}, {"ug": "атиңиз", "ru": "ваш отец", "group": "ата"}, {"ug": "анимиз", "ru": "наша мать", "group": "ана"}, {"ug": "аниңиз", "ru": "ваша мать", "group": "ана"}, {"ug": "балимиз", "ru": "наш ребёнок", "group": "бала"}, {"ug": "балиңиз", "ru": "ваш ребёнок", "group": "бала"}, {"ug": "балам", "ru": "мой ребёнок", "group": "бала"}, {"ug": "балиси", "ru": "его ребёнок", "group": "бала"}, {"ug": "қизимиз", "ru": "наша дочь", "group": "қиз"}, {"ug": "қизиңиз", "ru": "ваша дочь", "group": "қиз"}]'::jsonb);
