insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('hotan-g1', 'hotan', 4, 'Мениң атам', '{}'::int[], 'phrases', '{"text": "Чтобы подчеркнуть, чей, перед словом говорят: мениң (мой), сениң (твой), униң (его, её), бизниң (наш), сизниң (ваш). Окончание остаётся.", "examples": [{"ug": "мениң атам", "ru": "мой отец"}, {"ug": "сениң анаң", "ru": "твоя мать"}, {"ug": "униң қизи", "ru": "его дочь"}, {"ug": "сизниң исмиңиз", "ru": "ваше имя"}]}'::jsonb, '[{"ug": "мениң анам", "ru": "моя мать", "wrong": ["сениң", "аниси"]}, {"ug": "сениң акаң", "ru": "твой старший брат", "wrong": ["мениң", "акам"]}, {"ug": "униң қизи", "ru": "его дочь", "wrong": ["бизниң", "қизим"]}, {"ug": "бизниң балимиз", "ru": "наш ребёнок", "wrong": ["сизниң", "балиңиз"]}, {"ug": "мениң исмим", "ru": "моё имя", "wrong": ["сениң", "исмиң"]}, {"ug": "сизниң исмиңиз", "ru": "ваше имя", "wrong": ["мениң", "исмим"]}, {"ug": "униң дадиси", "ru": "его папа", "wrong": ["мениң", "дадам"]}, {"ug": "сениң укаң", "ru": "твой младший брат", "wrong": ["униң", "укиси"]}]'::jsonb);
