insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('hotan-g2', 'hotan', 8, 'У меня есть', '{}'::int[], 'phrases', '{"text": "«У меня есть» — мениң … бар. «Нет» — йоқ. Вопрос задают частицей -му: барму?", "examples": [{"ug": "Мениң акам бар", "ru": "У меня есть старший брат"}, {"ug": "Мениң укам йоқ", "ru": "У меня нет младшего брата"}, {"ug": "Сениң итиң барму?", "ru": "У тебя есть собака?"}]}'::jsonb, '[{"ug": "Мениң акам бар", "ru": "У меня есть старший брат", "wrong": ["йоқ", "акаң"]}, {"ug": "Мениң итим бар", "ru": "У меня есть собака", "wrong": ["йоқ", "ити"]}, {"ug": "Униң қизи бар", "ru": "У него есть дочь", "wrong": ["мениң", "қизим"]}, {"ug": "Мениң укам йоқ", "ru": "У меня нет младшего брата", "wrong": ["бар", "укаң"]}, {"ug": "Сениң итиң барму?", "ru": "У тебя есть собака?", "wrong": ["мениң", "бар"]}, {"ug": "Бизниң балимиз бар", "ru": "У нас есть ребёнок", "wrong": ["йоқ", "балиси"]}]'::jsonb);
