insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('ghulja-g1', 'ghulja', 3, 'Это…', '{}'::int[], 'phrases', '{"text": "«Это» — бу. Слово «есть, является» не нужно: Бу китап — Это книга. Вопросы: Бу немә? — Что это? Бу ким? — Кто это?", "examples": [{"ug": "Бу китап", "ru": "Это книга"}, {"ug": "Бу немә?", "ru": "Что это?"}, {"ug": "Бу ким?", "ru": "Кто это?"}]}'::jsonb, '[{"ug": "Бу немә?", "ru": "Что это?", "wrong": ["ким?", "у"]}, {"ug": "Бу китап", "ru": "Это книга", "wrong": ["немә", "дәптәр"]}, {"ug": "Бу ким?", "ru": "Кто это?", "wrong": ["немә?", "мән"]}, {"ug": "Бу мениң атам", "ru": "Это мой отец", "wrong": ["атиси", "сениң"]}, {"ug": "Бу мениң достум", "ru": "Это мой друг", "wrong": ["сениң", "униң"]}, {"ug": "Бу алма қизил", "ru": "Это яблоко красное", "wrong": ["сериқ", "нан"]}, {"ug": "Бу чирайлиқ гүл", "ru": "Это красивый цветок", "wrong": ["яман", "кичик"]}]'::jsonb);
