insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('ghulja-g2', 'ghulja', 8, 'Я ученик', '{}'::int[], 'phrases', '{"text": "«Я — ученик» говорят одним словом: оқуғучимән. Окончания: мән → -мән, сән → -сән, биз → -миз, сиз → -сиз. Для «он, она» окончание не нужно.", "examples": [{"ug": "Мән оқуғучимән", "ru": "Я ученик"}, {"ug": "Сән оқуғучисән", "ru": "Ты ученик"}, {"ug": "У муәллим", "ru": "Он учитель"}, {"ug": "Биз уйғурмиз", "ru": "Мы уйгуры"}]}'::jsonb, '[{"ug": "Мән оқуғучимән", "ru": "Я ученик", "wrong": ["оқуғучисән", "сән"]}, {"ug": "Сән оқуғучисән", "ru": "Ты ученик", "wrong": ["оқуғучимән", "мән"]}, {"ug": "У муәллим", "ru": "Он учитель", "wrong": ["муәллиммән", "мән"]}, {"ug": "Биз уйғурмиз", "ru": "Мы уйгуры", "wrong": ["уйғурмән", "сиз"]}, {"ug": "Сиз муәллимму?", "ru": "Вы учитель?", "wrong": ["муәллим", "биз"]}, {"ug": "Мән уйғурмән", "ru": "Я уйгур", "wrong": ["уйғурсән", "у"]}]'::jsonb);
