insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('aksu-g1', 'aksu', 3, 'Я пью чай', '{}'::int[], 'phrases', '{"text": "Настоящее время: к основе глагола добавляют -имән (я), -исән (ты), -иду (он, она), -имиз (мы), -исиз (вы). Если основа на гласную: -ймән, -йду.", "examples": [{"ug": "ичмәк → ичимән", "ru": "пить → я пью"}, {"ug": "бармақ → баримиз", "ru": "идти → мы идём"}, {"ug": "оқумақ → оқуйду", "ru": "читать → он читает"}]}'::jsonb, '[{"ug": "Мән чай ичимән", "ru": "Я пью чай", "wrong": ["ичиду", "сән"]}, {"ug": "Сән су ичисән", "ru": "Ты пьёшь воду", "wrong": ["ичимән", "мән"]}, {"ug": "У китап оқуйду", "ru": "Он читает книгу", "wrong": ["оқуймән", "мән"]}, {"ug": "Биз мәктәпкә баримиз", "ru": "Мы идём в школу", "wrong": ["барисиз", "мән"]}, {"ug": "Бала ухлайду", "ru": "Ребёнок спит", "wrong": ["ухлаймән", "ойнайду"]}, {"ug": "Улар ойнайду", "ru": "Они играют", "wrong": ["ойнаймән", "биз"]}, {"ug": "Мән уйғурчә сөзләймән", "ru": "Я говорю по-уйгурски", "wrong": ["сөзләйду", "сән"]}, {"ug": "Сиз немә қилисиз?", "ru": "Что вы делаете?", "wrong": ["қилимән", "ким"]}]'::jsonb);
