insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('aksu-g2', 'aksu', 7, 'Где? Куда?', '{}'::int[], 'phrases', '{"text": "«Где» — окончание -да, -дә, -та, -тә: өйдә — дома. «Куда» — -ға, -гә, -қа, -кә: мәктәпкә — в школу. Вопросы: қәйәрдә? — где? қәйәргә? — куда?", "examples": [{"ug": "өй → өйдә", "ru": "дом → дома"}, {"ug": "өй → өйгә", "ru": "дом → домой"}, {"ug": "мәктәп → мәктәптә", "ru": "в школе"}, {"ug": "мәктәп → мәктәпкә", "ru": "в школу"}]}'::jsonb, '[{"ug": "Атам өйдә", "ru": "Мой отец дома", "wrong": ["өйгә", "атиси"]}, {"ug": "Китап үстәлдә", "ru": "Книга на столе", "wrong": ["үстәлгә", "дәптәр"]}, {"ug": "Бала мәктәптә", "ru": "Ребёнок в школе", "wrong": ["мәктәпкә", "у"]}, {"ug": "Мән мәктәпкә баримән", "ru": "Я иду в школу", "wrong": ["мәктәптә", "барисән"]}, {"ug": "Сән қәйәргә барисән?", "ru": "Куда ты идёшь?", "wrong": ["қәйәрдә", "баримән"]}, {"ug": "Анаң қәйәрдә?", "ru": "Где твоя мать?", "wrong": ["анам", "қәйәргә"]}, {"ug": "Биз өйгә баримиз", "ru": "Мы идём домой", "wrong": ["өйдә", "барисиз"]}]'::jsonb);
