insert into levels (id, section_id, position, title, word_ids, kind, rule, items) values ('urumqi-g1', 'urumqi', 5, 'О себе', '{}'::int[], 'phrases', '{"text": "Соберём всё вместе и расскажем о себе: как зовут, где живёшь, что делаешь.", "examples": [{"ug": "Мениң исмим Алим", "ru": "Меня зовут Алим"}, {"ug": "Мән мәктәптә оқуймән", "ru": "Я учусь в школе"}]}'::jsonb, '[{"ug": "Мениң исмим Алим", "ru": "Меня зовут Алим", "wrong": ["исмиң", "сениң"]}, {"ug": "Сениң исмиң немә?", "ru": "Как тебя зовут?", "wrong": ["исмим", "ким"]}, {"ug": "Мениң икки укам бар", "ru": "У меня два младших брата", "wrong": ["бир", "укиси"]}, {"ug": "Мән Алмутида яшаймән", "ru": "Я живу в Алматы", "wrong": ["Алмутиға", "яшайду"]}, {"ug": "Мән мәктәптә оқуймән", "ru": "Я учусь в школе", "wrong": ["мәктәпкә", "оқуйду"]}, {"ug": "Мән уйғурчә оқуймән", "ru": "Я читаю по-уйгурски", "wrong": ["оқуйду", "сән"]}, {"ug": "Мән сизни яхши көримән", "ru": "Я вас люблю", "wrong": ["сән", "көриду"]}]'::jsonb);
