insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('doppa', 1, 'Что такое доппа', 'Детям', 2, 'doppa', 200, array['Доппа — уйгурская шапочка. Её носят мальчики и девочки, мужчины и женщины.','У доппы четыре стороны, поэтому сверху она похожа на квадрат. Её можно сложить пополам и положить в карман.','Мужская доппа чаще всего чёрная, с белым узором «бадам». «Бадам» значит «миндаль»: узор похож на миндальный орешек.','Женские доппы яркие: их вышивают цветами, золотыми нитками, иногда бусинами. Посмотри на Алима и Райхан — у них тоже доппы!']::text[], '[{"question": "Сколько сторон у доппы?", "options": ["Три", "Четыре", "Шесть"], "answer": 1}, {"question": "На что похож узор «бадам»?", "options": ["На миндаль", "На звезду", "На гранат"], "answer": 0}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('kashgari', 2, 'Махмуд Кашгари и его словарь', 'Взрослым', 4, 'book', 68, array['Махмуд Кашгари — учёный XI века. Он родом из окрестностей Кашгара, отсюда и его имя.','В 1070-х годах в Багдаде он написал книгу «Диван лугат ат-турк», «Собрание тюркских наречий». Это словарь тюркских языков с объяснениями на арабском.','В книге собраны не только слова, но и пословицы, стихи и рассказы о жизни тюркских народов. В неё вошла и круглая карта мира, какой её видел автор.','Многие слова из словаря Кашгари уйгуры узнают и сегодня. Мавзолей учёного находится в селении Опал недалеко от Кашгара.']::text[], '[{"question": "В каком веке жил Махмуд Кашгари?", "options": ["В XI веке", "В XV веке", "В XIX веке"], "answer": 0}, {"question": "На каком языке написаны объяснения в словаре?", "options": ["На персидском", "На арабском", "На русском"], "answer": 1}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('muqam', 3, 'Двенадцать мукамов', 'Детям и взрослым', 3, 'music', 286, array['Мукам — большое музыкальное произведение, в котором соединяются песни, танцы и игра на инструментах.','Главных мукамов двенадцать. Если исполнить их все подряд, музыка будет звучать больше суток.','Мукамы играют на рабабе, дутаре и сатаре, а ритм отбивают на бубне — дапе.','В 2005 году ЮНЕСКО признало уйгурский мукам шедевром устного и нематериального наследия человечества.']::text[], '[{"question": "Сколько главных мукамов?", "options": ["Семь", "Двенадцать", "Сорок"], "answer": 1}, {"question": "Как называется уйгурский бубен?", "options": ["Дап", "Дутар", "Рабаб"], "answer": 0}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('yusuf', 4, 'Юсуф Хас Хаджиб и «Благодатное знание»', 'Взрослым', 4, 'scroll', 205, array['Юсуф родился в начале XI века в городе Баласагун. Он много учился и стал поэтом и мудрецом.','В 1069 году в Кашгаре он закончил большую поэму «Кутадгу билиг» — «Благодатное знание». В ней больше шести тысяч двустиший.','Поэма написана как беседа четырёх героев: правителя, его визиря, сына визиря и отшельника. Они спорят о том, как справедливо править и как жить достойно.','Юсуф преподнёс поэму правителю Кашгара и получил почётное звание «хас хаджиб» — главный советник при дворе. Его мавзолей стоит в Кашгаре.']::text[], '[{"question": "Как переводится название поэмы «Кутадгу билиг»?", "options": ["Благодатное знание", "Книга дорог", "Песни степи"], "answer": 0}, {"question": "В каком городе Юсуф закончил поэму?", "options": ["В Хотане", "В Кашгаре", "В Турфане"], "answer": 1}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('amannisa', 5, 'Аманнисахан и мукамы', 'Детям и взрослым', 3, 'queen', 286, array['Аманнисахан жила в XVI веке в Яркенде. С детства она писала стихи и играла на музыкальных инструментах.','По преданию, правитель Яркенда Абдурашид-хан услышал её игру и пение и взял её в жёны. Так девушка из простой семьи стала ханшей.','Аманнисахан заметила, что старые напевы забываются и звучат у всех по-разному. Вместе с музыкантом Кидирханом она собрала и упорядочила их.','Так сложились двенадцать мукамов, которые уйгуры играют до сих пор. Аманнисахан помнят как покровительницу уйгурской музыки.']::text[], '[{"question": "В каком городе жила Аманнисахан?", "options": ["В Яркенде", "В Кульдже", "В Аксу"], "answer": 0}, {"question": "Что она собрала вместе с Кидирханом?", "options": ["Сказки", "Мукамы", "Пословицы"], "answer": 1}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('karez', 6, 'Карезы: реки под землёй', 'Детям', 3, 'karez', 81, array['Турфан — одно из самых жарких и сухих мест. Дождей тут почти нет, зато высоко в горах лежит снег.','Весной снег тает, и вода уходит под землю. Люди придумали, как её достать: они копали ряд колодцев и соединяли их тоннелем. Такой подземный канал называется карез.','Тоннель идёт под уклон, поэтому вода сама бежит к садам. Под землёй солнце её не нагревает, и она не испаряется.','В Турфане больше тысячи карезов. Благодаря им здесь растут сладкий виноград и дыни, хотя вокруг пустыня.']::text[], '[{"question": "Откуда берётся вода в карезах?", "options": ["Из моря", "Из тающего снега в горах", "Из дождя"], "answer": 1}, {"question": "Почему вода в карезе не испаряется?", "options": ["Она течёт под землёй", "Её накрывают крышками", "Она очень холодная"], "answer": 0}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('aydingkol', 7, 'Айдинкөль — лунное озеро', 'Детям', 2, 'lake', 144, array['Недалеко от Турфана лежит озеро Айдинкөль. «Көл» по-уйгурски — «озеро», а всё название переводят как «лунное озеро».','Это одно из самых низких мест на суше: дно впадины лежит примерно на 150 метров ниже уровня моря.','Воды в озере почти не осталось. Его покрывает белая корка соли, которая блестит на солнце, как луна.','Из-за того что впадина такая глубокая, летом в ней очень жарко. Турфан часто называют самым жарким местом Китая.']::text[], '[{"question": "Что значит слово «көл»?", "options": ["Гора", "Озеро", "Река"], "answer": 1}, {"question": "Почему озеро блестит?", "options": ["Его покрывает соль", "В нём много рыбы", "В нём отражаются горы"], "answer": 0}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('silkroad', 8, 'Шёлковый путь через Кашгар', 'Детям и взрослым', 3, 'caravan', 112, array['Шёлковый путь — это не одна дорога, а много караванных путей между Китаем и странами у Средиземного моря. Название придумал немецкий учёный в XIX веке.','Пустыню Такла-Макан караваны обходили с севера и с юга. Обе дороги сходились в Кашгаре, а оттуда путь шёл через высокие горы Памира.','Товары везли на верблюдах: шёлк, бумагу, фарфор, нефрит, пряности. Ночевали в караван-сараях — постоялых дворах для людей и животных.','По Шёлковому пути путешествовали не только товары, но и идеи: книги, музыка, ремёсла, религии. Поэтому Кашгар веками был городом многих языков.']::text[], '[{"question": "На каких животных везли товары?", "options": ["На лошадях", "На верблюдах", "На слонах"], "answer": 1}, {"question": "Где сходились северная и южная дороги?", "options": ["В Кашгаре", "В Хотане", "В Урумчи"], "answer": 0}]'::jsonb);
insert into stories (id, position, title, audience, minutes, art, word_id, paragraphs, quiz) values ('scripts', 9, 'Как писали уйгуры', 'Взрослым', 4, 'letters', 282, array['Больше тысячи лет назад древние уйгуры писали руническим письмом: буквы вырезали на камнях. Потом появился древнеуйгурский алфавит, он произошёл от согдийского письма.','Древнеуйгурским письмом писали сверху вниз. Его позже взяли монголы, а от монгольского письма пошло маньчжурское.','Вместе с исламом пришла арабская графика. На ней веками писали стихи, книги и письма. Её же используют уйгуры в Синьцзяне и сегодня.','В современной уйгурской арабице 32 буквы, и все гласные пишутся, поэтому слово читается так, как написано. А уйгуры Казахстана и Кыргызстана пишут кириллицей, как в этом приложении.']::text[], '[{"question": "От какого письма произошёл древнеуйгурский алфавит?", "options": ["От согдийского", "От греческого", "От латинского"], "answer": 0}, {"question": "Сколько букв в современной уйгурской арабице?", "options": ["24", "32", "40"], "answer": 1}]'::jsonb);
